<script setup lang="ts">
import { useAccountSecurity, sessionLocalTime } from '../../composables/useAccountSecurity';
import StatePanel from '../../components/ui/StatePanel.vue';
import AppPagination from '../../components/ui/AppPagination.vue';
const security = useAccountSecurity();
const { auth, data, loading, error, page, size, currentPassword, newPassword, confirmation, othersPassword, formError, notice, needsUpgrade } = security;
</script>
<template>
  <div class="wordlist-page account-security"><header class="library-heading"><h1>账户安全与设备</h1><RouterLink to="/settings" class="muted-link">学习设置</RouterLink></header><p v-if="formError" class="inline-error" role="alert">{{ formError }}</p><p v-if="notice" class="sentence-notice" role="status">{{ notice }}</p>
    <section class="account-section" aria-labelledby="password-title"><h2 id="password-title">修改密码</h2><p class="subtle-copy">修改后所有设备退出，需用新密码重新登录。密码中的空格会保留。</p><form class="sentence-editor" novalidate @submit.prevent="security.password"><fieldset :disabled="auth.accountBusy"><label for="current-password">当前密码</label><input id="current-password" v-model="currentPassword" type="password" autocomplete="current-password" /><label for="new-password">新密码</label><input id="new-password" v-model="newPassword" type="password" autocomplete="new-password" /><label for="confirm-password">确认新密码</label><input id="confirm-password" v-model="confirmation" type="password" autocomplete="new-password" /><button class="btn btn-secondary">修改密码并重新登录</button></fieldset></form></section>
    <section class="account-section" aria-labelledby="sessions-title"><div class="sentence-linked-heading"><h2 id="sessions-title">登录设备</h2><button class="muted-link" :disabled="loading || auth.accountBusy" @click="security.refresh">刷新设备</button></div><p class="subtle-copy">设备名称由登录时自定义；以下时间已转为本地时间。最近刷新时间不代表每次使用时间。</p><StatePanel :loading="loading" :error="error" :empty="data?.total === 0" message="暂无可列出的有效设备会话，旧凭证可能尚未升级。" @retry="security.refresh" /><button v-if="needsUpgrade || data?.total === 0" class="btn btn-secondary" :disabled="auth.accountBusy" @click="security.upgrade">升级登录凭证</button><article v-for="session in !loading && !error ? data?.records : []" :key="session.sessionId" class="account-device-row"><div><h3>{{ session.deviceName }} <span v-if="session.current" class="learning-badge">当前会话</span></h3><dl><div><dt>登录</dt><dd>{{ sessionLocalTime(session.createdAt) }}</dd></div><div><dt>最近刷新</dt><dd>{{ sessionLocalTime(session.lastRefreshedAt) }}</dd></div><div><dt>到期</dt><dd>{{ sessionLocalTime(session.expiresAt) }}</dd></div></dl></div><button class="btn btn-secondary" :disabled="auth.accountBusy" @click="security.revoke(session)">{{ session.current ? '退出此设备' : '撤销会话' }}</button></article><AppPagination v-if="data" :page="page" :size="size" :total="data.total" :disabled="loading || auth.accountBusy" @change="page = $event; security.refresh()" />
      <form class="sentence-editor" novalidate @submit.prevent="security.logoutOthers"><fieldset :disabled="auth.accountBusy"><label for="others-password">验证当前密码，退出其他设备</label><input id="others-password" v-model="othersPassword" type="password" autocomplete="current-password" /><button class="btn btn-secondary">退出其他设备</button></fieldset></form>
    </section>
  </div>
</template>
